{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청의 목적과 제약을 바탕으로 구현 범위를 구체화할 수 있는지 확인한다. 개발 담당 팀원과 범위를 조정할 때 적용한 요구사항 선정 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "서비스 요구사항을 정리하면서 개발 담당 팀원과 구현 범위를 조정해야 했던 상황이 제시된다.",
          "task": "서비스의 목적과 구현 제약에 맞춰 이번에 구현할 요구사항의 경계를 정해야 했다는 과제가 드러난다.",
          "action": "구현 범위를 나눈 기준을 제시하고, 실제 요구사항에 그 기준을 적용한 판단을 설명한다.",
          "result": "해당 기준에 따라 정해진 구현 범위가 구체적으로 드러난다. 실제 출시나 성과 수치까지 제시할 필요는 없다."
        },
        "expectedEvidence": [
          "요구사항의 구현 범위를 나눌 때 실제로 적용한 기준",
          "그 기준이 해결하려는 문제나 당시의 구현 제약에 적합했던 이유",
          "기준을 적용한 구체적인 요구사항과 그에 따라 정해진 범위"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨던데요, 그때 요구사항의 구현 범위를 나눈 기준은 무엇이었어요?",
      "answerTip": "기억나는 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 나눈 기준을 명확하게 제시하고, 해당 기준이 서비스 목적이나 당시 제약에 적합했던 이유를 설명한다.",
            "실제 요구사항에 기준을 적용한 사례를 통해 구현 범위의 경계가 구체적으로 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 나눈 기준은 제시하지만, 서비스 목적이나 제약과의 연결 설명이 제한적이다.",
            "기준을 적용한 요구사항이나 결정된 범위가 일부 드러나지만 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 나눈 기준을 제시하지 못하고 요구사항을 정리했다는 설명에 그친다.",
            "제시한 기준과 실제 범위 결정의 연결이 드러나지 않거나, 화면 표현 등 다른 주제로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서 기능 흐름이 끊기지 않도록 화면의 상태 변화를 구체적으로 설계할 수 있는지 확인한다. 직접 작성한 화면설계서에 담긴 예외 상황 하나의 상태 전환 설계에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약·취소·알림 흐름 중 화면 상태가 달라져야 하는 예외 상황 하나가 제시된다.",
          "task": "해당 예외가 발생했을 때 화면이 어떤 상태로 전환되어야 하는지 정해야 했다는 과제가 드러난다.",
          "action": "예외 발생 조건과 그에 따른 화면의 상태 변화를 구체적으로 설명한다.",
          "result": "예외 발생 후 사용자가 보게 되는 화면 상태가 분명해진다. 구현 완료나 사용자 검증 결과까지 제시할 필요는 없다."
        },
        "expectedEvidence": [
          "예외 상황 하나에 대해 실제로 설계한 화면의 상태 변화",
          "해당 상태 전환을 일으키는 조건과 전환 전후의 차이",
          "설계된 상태 변화가 해당 예외 상황에 맞는 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 그때 예외 상황 하나에서 화면의 상태 변화를 어떻게 설계하셨어요?",
      "answerTip": "당시 장면을 떠올리며 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 예외 상황 하나를 바탕으로 발생 조건과 화면의 전환 전후 상태를 명확하게 설명한다.",
            "화면 상태의 변화가 해당 예외 상황에 적합하며, 설명만으로도 화면에서 달라지는 내용을 파악할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황과 그에 따른 화면 변화는 제시하지만, 발생 조건이나 전환 전후 상태의 설명이 일부 부족하다.",
            "설계 방향은 예외 상황에 부합하나 실제 화면의 변화를 구체적으로 파악하기에는 설명이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 고려했다는 언급만 있고 실제로 설계한 화면 상태의 변화가 드러나지 않는다.",
            "화면설계 도구나 문서 분량만 설명하거나, 제시한 화면 변화가 해당 예외 상황과 연결되지 않는다."
          ]
        }
      }
    }
  ]
}
